// Tenant Authentication & Payload Sanitization Middleware
const headers = $input.first().json.headers || {};
const body = $input.first().json.body || {};

// Extract tenant identity from headers or body
const tenantId = (headers['x-tenant-id'] || body.tenant_id || body.tenantId || '').trim();
const workspaceId = (headers['x-workspace-id'] || body.workspace_id || body.workspaceId || 'default').trim();
const queryText = (body.query || body.prompt || body.message || '').trim();
const topK = Number(body.top_k || body.limit || 5);
const scoreThreshold = Number(body.score_threshold || 0.68);
const categoryFilter = body.category || null;

// Security Check - Tenant ID is strictly mandatory
if (!tenantId) {
  return [{
    json: {
      isAuthenticated: false,
      errorCode: 'ERR_MISSING_TENANT_ID',
      errorMessage: 'Security Exception: x-tenant-id header or tenant_id body parameter is required.',
      statusCode: 401
    }
  }];
}

if (!queryText) {
  return [{
    json: {
      isAuthenticated: false,
      errorCode: 'ERR_EMPTY_QUERY',
      errorMessage: 'Query validation failed: query string cannot be empty.',
      statusCode: 400
    }
  }];
}

return [{
  json: {
    isAuthenticated: true,
    tenant_id: tenantId,
    workspace_id: workspaceId,
    query: queryText,
    top_k: topK,
    score_threshold: scoreThreshold,
    category_filter: categoryFilter,
    session_id: body.session_id || `session_${Date.now()}`,
    received_at: new Date().toISOString()
  }
}];

// Prepare Qdrant Search Payload with Strict Tenant Filtering
const authData = $('Tenant Auth & Payload Middleware').item.json;
const embData = $input.first().json;

const vector = embData.data && embData.data[0] ? embData.data[0].embedding : null;
if (!vector) {
  throw new Error('Failed to generate vector embedding from OpenAI API.');
}

// Construct immutable tenant pre-filter
const mustConditions = [
  {
    key: "tenant_id",
    match: { value: authData.tenant_id }
  }
];

if (authData.workspace_id && authData.workspace_id !== 'default') {
  mustConditions.push({
    key: "workspace_id",
    match: { value: authData.workspace_id }
  });
}

if (authData.category_filter) {
  mustConditions.push({
    key: "category",
    match: { value: authData.category_filter }
  });
}

const qdrantPayload = {
  vector: vector,
  limit: authData.top_k || 5,
  with_payload: true,
  with_vector: false,
  score_threshold: authData.score_threshold || 0.65,
  filter: {
    must: mustConditions
  }
};

return [{
  json: {
    ...authData,
    qdrant_payload: qdrantPayload
  }
}];

// Context Formatter & Relevance Scoring Gate
const rawResult = $input.first().json;
const authData = $('Tenant Auth & Payload Middleware').item.json;
const points = rawResult.result || [];

if (!points || points.length === 0) {
  return [{
    json: {
      ...authData,
      context_found: false,
      context_text: 'No relevant internal tenant documentation found for this query.',
      citations: [],
      avg_score: 0
    }
  }];
}

let totalScore = 0;
const citations = [];
const formattedChunks = [];

points.forEach((pt, idx) => {
  const payload = pt.payload || {};
  const score = pt.score || 0;
  totalScore += score;

  const docId = payload.document_id || `doc_${idx + 1}`;
  const title = payload.title || payload.filename || 'Documentation';
  const content = payload.content || payload.text || '';

  citations.push({
    document_id: docId,
    title: title,
    score: Number(score.toFixed(4)),
    category: payload.category || 'general'
  });

  formattedChunks.push(`### Source [${idx + 1}] - ${title} (DocID: ${docId}, Relevance: ${(score * 100).toFixed(1)}%)\n${content}`);
});

const avgScore = Number((totalScore / points.length).toFixed(4));

return [{
  json: {
    ...authData,
    context_found: true,
    context_text: formattedChunks.join('\n\n'),
    citations: citations,
    avg_score: avgScore,
    chunk_count: points.length
  }
}];

