// Assemble Final Production Response Object
const synth = $input.first().json;
const ctx = $('Format Context & Citations').item.json;

const answer = synth.choices && synth.choices[0] && synth.choices[0].message
  ? synth.choices[0].message.content
  : (ctx.context_found ? 'Error synthesizing response from context.' : 'No relevant documentation found for your query.');

const usage = synth.usage || {};

return [{
  json: {
    status: 'success',
    tenant_id: ctx.tenant_id,
    workspace_id: ctx.workspace_id,
    query: ctx.query,
    answer: answer,
    citations: ctx.citations,
    grounding_metrics: {
      context_found: ctx.context_found,
      chunks_retrieved: ctx.chunk_count || 0,
      average_similarity: ctx.avg_score || 0
    },
    llm_usage: {
      prompt_tokens: usage.prompt_tokens || 0,
      completion_tokens: usage.completion_tokens || 0,
      total_tokens: usage.total_tokens || 0
    },
    generated_at: new Date().toISOString()
  }
}];
